fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2.
    if n < 2 {
        return false;
    }

    // Check for any divisor k with 2 <= k < n.
    // Work in i16 to avoid overflow concerns when incrementing and taking modulo.
    let n16 = n as i16;
    let mut k: i16 = 2;

    while k < n16 {
        if n16 % k == 0 {
            return false;
        }
        k += 1; // termination measure (n - k) strictly decreases each iteration
    }

    true
}